<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientRequestObjectSigningAlgAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientRequestObjectSigningAlgAccessor trait.
 *
 * Covers null default, string/VO assignment via withRequestObjectSigningAlg,
 * getRequestObjectSigningAlg/requestObjectSigningAlg accessors, and isRequestObjectSigningAlgChanged with/without original.
 */
class TrustedClientRequestObjectSigningAlgAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRequestObjectSigningAlg creates a new instance with the RequestObjectSigningAlg set
     * from a string value, and getRequestObjectSigningAlg returns the primitive string.
     */
    public function testWithRequestObjectSigningAlgFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientRequestObjectSigningAlgAccessorUnitTest();

        // Act
        $result = $holder->withRequestObjectSigningAlg('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getRequestObjectSigningAlg());
    }
    /**
     * Asserts that withrequestObjectSigningAlg has access to the value object
     * from a string value, and getRequestObjectSigningAlg returns the primitive string.
     */
    public function testWithRequestObjectSigningAlgFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientRequestObjectSigningAlgAccessorUnitTest();

        // Act
        $result = $holder->withRequestObjectSigningAlg('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->requestObjectSigningAlg()->value());
    }
    public function testChangedRequestObjectSigningAlg(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientRequestObjectSigningAlgAccessorUnitTest();
        $original = $holder->withRequestObjectSigningAlg('one');
        $same = $holder->withRequestObjectSigningAlg('one');
        $modified = $holder->withRequestObjectSigningAlg('other');

        // Act
        $unchanged = $holder->isRequestObjectSigningAlgChanged();
        $withSame = $original->isRequestObjectSigningAlgChanged($same);
        $withDiferent = $original->isRequestObjectSigningAlgChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientRequestObjectSigningAlgAccessorUnitTest
{
    use TrustedClientRequestObjectSigningAlgAccessor;
}
